/**
 * Stripe client for the cron worker service.
 *
 * Worker-local mirror of lib/stripe/client.ts.
 * NEVER imports from next/* — workers are a separate Railway service.
 *
 * Lazy singleton — constructed on first call so module evaluation
 * does not throw at startup when STRIPE_SECRET_KEY is absent.
 */
import Stripe from 'stripe'

let _stripe: Stripe | null = null

export function getStripe(): Stripe {
  if (!_stripe) {
    const key = process.env.STRIPE_SECRET_KEY
    if (!key) {
      throw new Error(
        '[InkOS workers] STRIPE_SECRET_KEY is not set. Add it to the Railway cron service env.',
      )
    }
    _stripe = new Stripe(key, {
      apiVersion: '2026-04-22.dahlia',
      appInfo: { name: 'InkOS-cron' },
    })
  }
  return _stripe
}

/**
 * Payments reconciliation cron — runs hourly at :05.
 *
 * Phase A — Dodo subscriptions: lists all active Dodo subscriptions via API,
 *   compares against the `subscriptions` table, logs any drift.
 *
 * Phase B — Stripe charges: loads PaymentIntents created in the last 25 hours
 *   from the Stripe API, compares against the `stripe_charges` table, logs drift.
 *
 * Phase C — writes a structured reconciliation report to the pino logger.
 *   No writes to the DB in S14 — `reconciliation_reports` table deferred to S15+.
 *
 * Resilience: Phase A and Phase B are independent. If one throws, the other
 * still completes. Both results are captured before logging.
 *
 * Idempotent: read-only in S14, no mutation risk on restart.
 */

import cron from 'node-cron'
import type { SupabaseClient } from '@supabase/supabase-js'
import type { SubscriptionListResponse } from 'dodopayments/resources/subscriptions.js'
import type Stripe from 'stripe'
import { supabase } from '../lib/supabase'
import { logger } from '../lib/logger'
import { getStripe } from './shared/stripe'
import { getDodo } from './shared/dodo'

// ─── Types ────────────────────────────────────────────────────────────────────

interface DodoDrift {
  in_api_not_in_db: string[]
  in_db_not_in_api: string[]
  status_mismatch: Array<{ id: string; api: string; db: string }>
}

interface StripeDrift {
  in_api_not_in_db: string[]
  status_mismatch: Array<{ charge_id: string; api: string; db: string }>
  amount_mismatch: Array<{ charge_id: string; api_cents: bigint; db_cents: bigint }>
}

interface ReconciliationReport {
  dodo: DodoDrift | { error: string }
  stripe: StripeDrift | { error: string }
  duration_ms: number
  ran_at: string
}

// ─── Dodo reconciliation ──────────────────────────────────────────────────────

async function reconcileDodo(client: SupabaseClient): Promise<DodoDrift> {
  const dodo = getDodo()

  // Collect all active subscriptions from Dodo via auto-paginating iterator
  const apiSubs = new Map<string, SubscriptionListResponse>()
  for await (const sub of dodo.subscriptions.list({ status: 'active', page_size: 100 })) {
    apiSubs.set(sub.subscription_id, sub)
  }

  // Load our DB state — only active subscriptions with a dodo_subscription_id
  const { data: dbRows, error: dbErr } = await client
    .from('subscriptions')
    .select('id, dodo_subscription_id, status')
    .eq('status', 'active')
    .not('dodo_subscription_id', 'is', null)

  if (dbErr) {
    throw new Error(`reconcileDodo: DB query failed — ${dbErr.message}`)
  }

  const dbMap = new Map<string, { id: string; status: string }>(
    (dbRows ?? []).map((row) => [row.dodo_subscription_id as string, { id: row.id, status: row.status }]),
  )

  const drift: DodoDrift = {
    in_api_not_in_db: [],
    in_db_not_in_api: [],
    status_mismatch: [],
  }

  for (const [subId, apiSub] of apiSubs) {
    const dbRow = dbMap.get(subId)
    if (!dbRow) {
      drift.in_api_not_in_db.push(subId)
    } else if (dbRow.status !== apiSub.status) {
      drift.status_mismatch.push({ id: subId, api: apiSub.status, db: dbRow.status })
    }
  }

  for (const dbSubId of dbMap.keys()) {
    if (!apiSubs.has(dbSubId)) {
      drift.in_db_not_in_api.push(dbSubId)
    }
  }

  return drift
}

// ─── Stripe reconciliation ────────────────────────────────────────────────────

/**
 * DB row shape for stripe_charges.
 * Typed inline because lib/supabase/types.ts has not been regenerated
 * after the 20260505100000 migration yet — regenerate with `pnpm db:types`.
 */
interface StripeChargeDbRow {
  id: string
  charge_id: string | null
  payment_intent_id: string
  status: string
  amount_cents: string | number   // Supabase returns bigint as string
}

async function reconcileStripe(client: SupabaseClient): Promise<StripeDrift> {
  const stripe = getStripe()

  // 25-hour window provides a safe overlap with the previous hourly run
  const sinceUnix = Math.floor((Date.now() - 25 * 60 * 60 * 1000) / 1000)
  const sinceIso = new Date(sinceUnix * 1000).toISOString()

  // Collect all charges in the window via Stripe's auto-paginating iterator
  const apiCharges = new Map<string, Stripe.Charge>()
  for await (const charge of stripe.charges.list({ created: { gte: sinceUnix }, limit: 100 })) {
    apiCharges.set(charge.id, charge)
  }

  // Load our DB state for the same window — only rows that have a charge_id
  const { data: dbRows, error: dbErr } = await client
    .from('stripe_charges')
    .select('id, charge_id, payment_intent_id, status, amount_cents')
    .gte('created_at', sinceIso)
    .not('charge_id', 'is', null)

  if (dbErr) {
    throw new Error(`reconcileStripe: DB query failed — ${dbErr.message}`)
  }

  const dbMap = new Map<string, StripeChargeDbRow>(
    ((dbRows ?? []) as StripeChargeDbRow[]).map((row) => [row.charge_id as string, row]),
  )

  const drift: StripeDrift = {
    in_api_not_in_db: [],
    status_mismatch: [],
    amount_mismatch: [],
  }

  for (const [chargeId, apiCharge] of apiCharges) {
    const dbRow = dbMap.get(chargeId)
    if (!dbRow) {
      drift.in_api_not_in_db.push(chargeId)
      continue
    }

    // Status comparison
    if (dbRow.status !== apiCharge.status) {
      drift.status_mismatch.push({
        charge_id: chargeId,
        api: apiCharge.status,
        db: dbRow.status,
      })
    }

    // Amount comparison — all money is bigint (cents)
    const dbCents = BigInt(dbRow.amount_cents)
    const apiCents = BigInt(apiCharge.amount)
    if (dbCents !== apiCents) {
      drift.amount_mismatch.push({
        charge_id: chargeId,
        api_cents: apiCents,
        db_cents: dbCents,
      })
    }
  }

  return drift
}

// ─── Report writer ────────────────────────────────────────────────────────────

function writeReconciliationReport(report: ReconciliationReport, runLog: ReturnType<typeof logger.child>): void {
  const hasDodoDrift = !('error' in report.dodo) && (
    report.dodo.in_api_not_in_db.length > 0 ||
    report.dodo.in_db_not_in_api.length > 0 ||
    report.dodo.status_mismatch.length > 0
  )

  const hasStripeDrift = !('error' in report.stripe) && (
    report.stripe.in_api_not_in_db.length > 0 ||
    report.stripe.status_mismatch.length > 0 ||
    report.stripe.amount_mismatch.length > 0
  )

  // Serialise BigInt fields for JSON logger
  const serialisable = {
    ...report,
    stripe: 'error' in report.stripe
      ? report.stripe
      : {
          ...report.stripe,
          amount_mismatch: report.stripe.amount_mismatch.map((m) => ({
            ...m,
            api_cents: m.api_cents.toString(),
            db_cents: m.db_cents.toString(),
          })),
        },
  }

  if (hasDodoDrift || hasStripeDrift || 'error' in report.dodo || 'error' in report.stripe) {
    runLog.warn(serialisable, 'payments-reconciliation: drift or errors detected')
  } else {
    runLog.info(serialisable, 'payments-reconciliation: clean — no drift detected')
  }

  // S14: logging only. Persist to reconciliation_reports table in S15+.
}

// ─── Main handler ─────────────────────────────────────────────────────────────

export async function runPaymentsReconciliation(): Promise<void> {
  const startedAt = Date.now()
  const runLog = logger.child({ cron: 'payments-reconciliation' })
  runLog.info('payments-reconciliation: starting run')

  // Phase A and B run independently — one failure does not abort the other
  const [dodoResult, stripeResult] = await Promise.all([
    reconcileDodo(supabase).catch((err: unknown) => {
      const message = err instanceof Error ? err.message : String(err)
      runLog.error({ err }, 'payments-reconciliation: Dodo phase failed')
      return { error: message } satisfies { error: string }
    }),
    reconcileStripe(supabase).catch((err: unknown) => {
      const message = err instanceof Error ? err.message : String(err)
      runLog.error({ err }, 'payments-reconciliation: Stripe phase failed')
      return { error: message } satisfies { error: string }
    }),
  ])

  const report: ReconciliationReport = {
    dodo: dodoResult,
    stripe: stripeResult,
    duration_ms: Date.now() - startedAt,
    ran_at: new Date().toISOString(),
  }

  writeReconciliationReport(report, runLog)
}

// ─── Cron schedule ────────────────────────────────────────────────────────────

// Every hour at :05 — slight offset avoids contention with :00 jobs
cron.schedule('5 * * * *', () => {
  runPaymentsReconciliation().catch((err: unknown) => {
    logger.error({ err }, 'cron: payments-reconciliation threw unexpectedly')
  })
})

